    # Check min degree
    if any(d < 4 for _, d in G.degree()):
        return False

    # Check max clique size
    # Use networkx.algorithms.clique.graph_clique_number is wrong, 
    # let's use nx.graph_clique_number if it exists, or just calculate it.
    # Actually, let's use nx.find_cliques(G)
    cliques = list(nx.find_cliques(G))
    if any(len(c) > 4 for c in cliques):
        return False

    # Check chromatic number
    # A graph is 5-colorable if we can assign colors 0-4.
    def can_color(graph, k):
        coloring = {}
        def backtrack(node):
            if node == 12:
                return True
            for color in range(k):
                if all(coloring.get(neighbor) != color for neighbor in graph.neighbors(node)):
                    coloring[node] = color
                    if backtrack(node + 1):
                        return True
                    del coloring[node]
            return False
        return backtrack(0)

    if not can_color(G, 5):
        return False

    return True

