fixed_edges = [(0,10), (0,11), (0,7), (3,10), (2,9), (1,9), (3,6)]

def solve():
    # Try to build a graph
    for _ in range(1000):
        edges = set(fixed_edges)

        # Add edges randomly, but check clique size as we go
        nodes = list(range(12))
        possible_edges = [e for e in itertools.combinations(nodes, 2) if e not in edges]
        random.shuffle(possible_edges)

        for u, v in possible_edges:
            G = nx.Graph()
            G.add_nodes_from(range(12))
            G.add_edges_from(edges)
            G.add_edge(u, v)

            # Check if adding (u, v) creates a clique of size 5
            cliques = list(nx.find_cliques(G))
            if all(len(c) <= 4 for c in cliques):
                edges.add((u, v))

            # Check if all degrees are >= 4
            if all(d >= 4 for _, d in G.degree()):
                if is_valid(edges):
                    return list(edges)

    return None

result = solve()
